"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6325],{26325:e=>{e.exports=JSON.parse('{"slug":"inflyaciya-ssha-sentyabr-2026-toplivo","locale":"zh","title":"高燃料价格将美国通胀推至3.7%，并传导至其他商品","description":"2026年九月美国通胀升至3.7%，核心2.6%。分析燃料如何传导至其他价格，以及俄罗斯数据显示什么。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年九月美国消费价格同比涨3.7%，八月3.4%，分析师预期3.6%。环比0.6%，一半以上来自汽油：九月涨9.1%，同比34.2%，整体能源同比20.4%。但核心通胀也从八月2.4%升至2.6%，高于2.5%预测。"},{"id":"b002","kind":"paragraph","text":"燃料这样传导：面包房开货车送面包，柴油变贵后先加配送费，几个月后商店将其并入面包价，买面包的咖啡店及厨师乘坐的出租车也变贵。这称二轮效应：单一价格冲击扩散至无直接关系项目。美联储《褐皮书》全部12地区报告都提及昂贵石油，企业抱怨柴油及贯穿供应链的燃料附加费。"},{"id":"b003","kind":"paragraph","text":"对美联储这是坏信号。九月加息四分之一个百分点后，当前3.75–4%。芝加哥联储主席奥斯坦\xb7古尔斯比称报告令人沮丧，服务通胀仍高于5%，几乎没降。十月27–28日加息概率由21.6%升至32.7%。美元报告后走强，美股下跌，标普500跌1.11%。"},{"id":"b004","kind":"paragraph","text":"俄罗斯燃料也比其他价格涨得快，但原因是炼厂中断和维修。若传入物流，其他商品也会涨。年初至十月12日汽油涨21.4%，柴油13.5%，总物价6.1%。十月6日至12日周通胀从公用事业调价造成的0.96%跳升后放缓至0.11%，但食品涨0.21%，鸡蛋2.4%。"},{"id":"b005","kind":"paragraph","text":"央行预计2026年6–7%。为不超7%，余下时间最多涨0.85%（1.07 / 1.061），约每周0.07%，而最近一周0.11%。央行调查分析师预计7.1%。监管机构将在十月23日公布新预测和利率决定。"},{"id":"b006","kind":"paragraph","text":"若燃料二轮效应较弱，周通胀回到0.07%或更低，央行可考虑降息。若配送、服务和食品继续跟随汽油上涨，14%利率持续更久，贷款仍贵，存款仍有收益。"},{"id":"b007","kind":"heading","text":"美国2026年九月通胀为何上升？"},{"id":"b008","kind":"paragraph","text":"主因汽油环比9.1%、同比34.2%，贡献一半以上月涨幅。但核心也由2.4%升至2.6%。美联储调查中的企业抱怨整条供应链燃料附加费，有的还抱怨进口关税。"},{"id":"b009","kind":"heading","text":"美联储会因通胀加息吗？"},{"id":"b010","kind":"paragraph","text":"尚未决定。报告后十月27–28日加息概率32.7%，此前21.6%。当前区间3.75–4%。"},{"id":"b011","kind":"heading","text":"俄罗斯2026年通胀能符合央行预测吗？"},{"id":"b012","kind":"paragraph","text":"年初至十月12日已涨6.1%。为不超过央行预测上沿7%，余下最多再涨0.85%。分析师预计7.1%，央行十月23日更新预测。"}],"sources":[{"label":"美国九月能源成本跃升，通胀加速","url":"https://finance.yahoo.com/economy/articles/inflation-surged-september-u-energy-125137111.html"},{"label":"企业向美联储警告燃料涨价推动其他价格","url":"https://finance.yahoo.com/economy/policy/articles/higher-fuel-costs-lead-price-192929072.html"},{"label":"古尔斯比称九月CPI令人沮丧","url":"https://finance.yahoo.com/economy/policy/articles/feds-goolsbee-says-september-cpi-193440276.html"},{"label":"美国通胀新闻推动美元、压低黄金","url":"https://finance.yahoo.com/markets/currencies/articles/dollar-ticks-gold-slides-on-us-inflation-news-193351444.html"},{"label":"美国通胀加速使华尔街周三下跌","url":"https://www.interfax.ru/business/1122532"},{"label":"俄罗斯十月6日至12日周通胀0.11%，同比升至7.22%","url":"https://www.interfax.ru/business/1122459"},{"label":"十月6日至12日通胀0.11%","url":"https://www.vedomosti.ru/economics/news/2026/10/14/1237099-inflyatsiya-sostavila"}],"sourceBodySha256":"28f2c644ef71d7bb0798565c5d39754497c35d4acc2f2fb91243b4680ba43a81"}')}}]);